function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3800);}
function persist(){if(!ready)return true;const ok=saveGame(save),indicator=$('#save-indicator');indicator.hidden=ok;indicator.textContent=ok?'':'Please back up your progress';if(!ok)toast('Browser could not save. Export a backup in Settings.');return ok;}
function theme(){for(const kind of ['background','tile','board']){const item=COSMETICS.find(c=>c.id===save.settings[kind]&&c.kind===kind);app.dataset[kind]=item?.id||({background:'mist',tile:'ivory',board:'sage'}[kind]);}app.classList.toggle('reduce-motion',save.settings.reduceMotion);$('#coins').textContent=save.coins;}
function chime(win=false){if(!save.settings.sound)return;try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const ctx=chime.ctx||(chime.ctx=new C());ctx.resume().catch(()=>{});(win?[523.25,659.25,783.99,1046.5]:[659.25,987.77]).forEach((f,i)=>{const osc=ctx.createOscillator(),gain=ctx.createGain(),t=ctx.currentTime+i*.09;osc.type='sine';osc.frequency.value=f;gain.gain.setValueAtTime(.0001,t);gain.gain.exponentialRampToValueAtTime(.06,t+.01);gain.gain.exponentialRampToValueAtTime(.0001,t+.27);osc.connect(gain).connect(ctx.destination);osc.start(t);osc.stop(t+.29);});}catch{}}
function levelFor(n){if(n<=levels.length)return levels[n-1];const choices=layouts.filter(l=>l.positions.length>=72&&l.positions.length<=144);const layout=choices[(n-levels.length-1)%choices.length];const seed=(Math.imul(n,2654435761)^0x6d2b79f5)>>>0;return {id:n,layoutId:layout.id,seed,difficulty:3,...generateDeal(layout,seed,3)};}
function startLevel(n){if(!ready||n>save.unlocked||n<1)return;const l=levelFor(n),layout=layoutMap.get(l.layoutId);save.level=n;save.game={...createGame(l,layout),level:n,completed:false};selected=null;hint=[];zoom=1;panX=panY=0;closeModal();render();persist();}
// Tile size in px; layouts use a half-tile grid (2 units per tile) and each layer shifts up-left.
const TW=60,TH=80,DX=5,DY=6;
function tilePos(t){return {x:t.x*TW/2-t.z*DX,y:t.y*TH/2-t.z*DY};}
function boardOrigin(tiles){const p=tiles.map(tilePos);return {x:Math.min(...p.map(q=>q.x)),y:Math.min(...p.map(q=>q.y)),w:Math.max(...p.map(q=>q.x)),h:Math.max(...p.map(q=>q.y))};}
function tileLabel(t){const suits={bamboo:'bamboo',char:'characters',dot:'circles',wind:['East wind','South wind','West wind','North wind'][t.val-1],dragon:['Red dragon','Green dragon','White dragon'][t.val-1],flower:'flower',season:'season'};return ['wind','dragon'].includes(t.suit)?suits[t.suit]:`${t.val} ${suits[t.suit]||t.suit}`;}
function render(){if(!save.game)return;theme();const n=save.level,g=save.game;$('#loading').hidden=true;$('#board-level').textContent=`Level ${n.toLocaleString()}`;$('#pairs-left').textContent=`${remaining(g.tiles)/2} pairs`;$('#undo-button').disabled=!g.history.length||g.completed;$('#shuffle-button').disabled=g.completed;$('#hint-button').disabled=g.completed;
 world.replaceChildren();const o=boardOrigin(g.tiles),PAD=8;bounds={w:o.w-o.x+TW+PAD*2+4,h:o.h-o.y+TH+PAD*2+8};world.style.width=bounds.w+'px';world.style.height=bounds.h+'px';
 const order=[...g.tiles].sort((a,b)=>a.z-b.z||a.y-b.y||a.x-b.x);order.forEach((t,i)=>{const b=document.createElement('button'),p=tilePos(t);b.className='tile';b.dataset.tile=t.id;b.hidden=!t.active;const free=isFree(t,g.tiles);b.classList.toggle('blocked',save.settings.showFree&&!free);b.classList.toggle('selected',selected===t.id);b.classList.toggle('hinted',hint.includes(t.id));b.setAttribute('aria-label',`${tileLabel(t)}. ${free?'Free':'Blocked'}`);b.setAttribute('aria-disabled',String(!free));b.setAttribute('aria-pressed',String(selected===t.id));b.style.cssText=`left:${p.x-o.x+PAD}px;top:${p.y-o.y+PAD}px;width:${TW}px;height:${TH}px;z-index:${i+1}`;b.innerHTML=`<img src="./assets/tiles/${spriteName(t.suit,t.val)}.svg" alt="" draggable="false">`;world.append(b);});resizeBoard();}
// Keep the zoom buttons off the tiles: reserve a strip along the bottom or the right, whichever leaves the board larger.
function resizeBoard(){if(!save.game)return;const r=viewport.getBoundingClientRect(),Z=56,bottom=Math.min((r.width-16)/bounds.w,(r.height-16-Z)/bounds.h),side=Math.min((r.width-16-Z)/bounds.w,(r.height-16)/bounds.h);band=side>bottom?{x:Z,y:0}:{x:0,y:Z};viewport.parentElement.classList.toggle('zoom-side',side>bottom);fit=Math.max(.1,Math.min(Math.max(side,bottom),1.6));transform();}
function transform(){const w=viewport.clientWidth,h=viewport.clientHeight,s=fit*zoom,limitX=Math.max(0,(bounds.w*s-w)/2)+16,limitY=Math.max(0,(bounds.h*s-h)/2)+16;panX=Math.max(-limitX,Math.min(limitX,panX));panY=Math.max(-limitY,Math.min(limitY,panY));world.style.transform=`translate(${(w-band.x-bounds.w*s)/2+panX}px,${(h-band.y-bounds.h*s)/2+panY}px) scale(${s})`;$('#zoom-fit').textContent=zoom===1?'Fit':Math.round(zoom*100)+'%';}
function setZoom(z){zoom=Math.max(1,Math.min(4,z));if(zoom===1)panX=panY=0;transform();}
function revealPair(ids){const o=boardOrigin(save.game.tiles),ps=ids.map(id=>tilePos(save.game.tiles[id]));const x=ps.reduce((s,p)=>s+p.x-o.x+8+TW/2,0)/2,y=ps.reduce((s,p)=>s+p.y-o.y+8+TH/2,0)/2;panX=(bounds.w/2-x)*fit*zoom;panY=(bounds.h/2-y)*fit*zoom;transform();}
function tapTile(id){if(!ready||save.game.completed||performance.now()<ignoreClickUntil)return;const g=save.game,t=g.tiles[id];if(!t?.active)return;if(!isFree(t,g.tiles)){return;}if(selected===id){selected=null;render();return;}if(selected!==null){if(isMatch(g.tiles[selected],t)){const ids=[selected,id];if(matchPair(g,...ids)){selected=null;hint=[];clearTimeout(hintTimer);chime();const win=remaining(g.tiles)===0;if(win){finish();}else{persist();render();ids.forEach(i=>{const el=world.querySelector(`[data-tile="${i}"]`);el.hidden=false;el.classList.add('matched');setTimeout(()=>{if(el.isConnected)el.hidden=true;},330);});if(!findHint(g.tiles))setTimeout(stuckDialog,350);}return;}}}selected=id;hint=[];render();}
function finish(){const first=!save.completed.includes(save.level);if(first){save.completed.push(save.level);save.coins+=25;}save.unlocked=Math.max(save.unlocked,save.level+1);save.game.completed=true;persist();render();chime(true);winDialog(first);}
function winDialog(first=false){openModal('',`<div class="win"><span class="win-flower" aria-hidden="true">✿</span><h2>Level ${save.level.toLocaleString()} complete</h2>${first?'<span class="reward">+25 ✧</span>':''}<button class="primary" data-action="next">Next level →</button><button class="secondary" data-action="journey" style="margin-top:12px;width:100%">Levels</button></div>`,'win');}
