function openModal(title,body,kind='other'){currentDialog=kind;$('#modal-content').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="close-modal" data-action="close" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div>`;if(!modal.open)modal.showModal();modal.scrollTop=0;}
