function settings(){const row=(key,label)=>`<label class="setting-row"><span>${label}</span><input type="checkbox" data-setting="${key}" ${save.settings[key]?'checked':''}></label>`;openModal('Settings',`${row('showFree','Dim blocked tiles','')}${row('sound','Sound','')}${row('reduceMotion','Reduce motion','')}<h3>Offline</h3><div id="offline-status" class="status-box" role="status">${esc(offlineMessage)}</div><div class="button-row"><button class="secondary" data-action="verify-offline">Check files</button><button class="secondary" data-action="repair-offline">Repair files</button><button class="secondary" data-action="update">Check for update</button>${updateReady?'<button class="primary" data-action="apply-update">Save &amp; update</button>':''}</div><h3>Backup</h3><div class="button-row"><button class="primary" data-action="backup">Export backup</button><button class="secondary" data-action="restore">Restore backup</button></div><p class="fine-print">L's Majong ${esc(VERSION)} · ${levels.length.toLocaleString()} levels · Engine adapted from myMahjong · Tiles by FluffyStuff (CC0) · GPL-3.0-only</p>`,'settings');}
function journey(page=Math.floor((save.level-1)/50)){if(!ready||!save.game)return;const max=Math.max(levels.length,save.unlocked),last=Math.ceil(max/50)-1;page=Math.max(0,Math.min(last,page));const start=page*50+1,end=Math.min(start+49,max);let html='';for(let n=start;n<=end;n++)html+=`<button class="level-button ${save.completed.includes(n)?'done':''} ${n===save.level?'current':''}" data-level="${n}" ${n>save.unlocked?'disabled':''} aria-label="Level ${n}${save.completed.includes(n)?', complete':n>save.unlocked?', locked':''}">${n}</button>`;openModal('Levels',`<div class="page-controls"><button data-page="${page-1}" ${page===0?'disabled':''} aria-label="Previous levels">‹</button><span>Levels ${start.toLocaleString()}–${end.toLocaleString()}</span><button data-page="${page+1}" ${page===last?'disabled':''} aria-label="Next levels">›</button></div><div class="journey-grid">${html}</div><button class="primary" data-action="continue">${save.game.completed?'Next level':'Continue level '+save.level}</button>`,'journey');}
function requestLevel(n){if(n===save.level){closeModal();if(save.game.completed)winDialog();return;}if(remaining(save.game.tiles)>0&&save.game.history.length){openModal('Leave this board?',`<p>Your current board will restart next time.</p><div class="button-row"><button class="primary" data-start-level="${n}">Go to level ${n}</button><button class="secondary" data-action="close">Stay</button></div>`,'confirm-level');}else startLevel(n);}
