function cosmetic(id){const c=COSMETICS.find(c=>c.id===id);if(!c)return;if(!save.owned.includes(id)&&c.price>0){if(save.coins<c.price){toast(`Needs ✧ ${c.price}`);return;}openModal(`Unlock ${esc(c.name)}?`,`<div class="button-row"><button class="primary" data-buy="${c.id}">Unlock for ✧ ${c.price}</button><button class="secondary" data-action="garden">Back</button></div>`,'purchase');return;}save.settings[c.kind]=id;if(!save.owned.includes(id))save.owned.push(id);persist();theme();garden();}
function buy(id){const c=COSMETICS.find(c=>c.id===id);if(!c||save.coins<c.price||save.owned.includes(id))return;save.coins-=c.price;save.owned.push(id);save.settings[c.kind]=id;persist();theme();garden();}
