function validateGameContent(candidate){if(!candidate.game)return true;const g=candidate.game;if(g.level!==candidate.level||g.levelId!==candidate.level||!Array.isArray(g.history)||g.tiles.some((t,i)=>t.id!==i||!['bamboo','char','dot','wind','dragon','flower','season'].includes(t.suit)||!Number.isInteger(t.val)||t.val<1||t.val>({'bamboo':9,char:9,dot:9,wind:4,dragon:3,flower:4,season:4}[t.suit])))return false;const l=levelFor(candidate.level),layout=layoutMap.get(l.layoutId);return layout&&g.layoutId===layout.id&&g.tiles.length===layout.positions.length&&g.tiles.every((t,i)=>['x','y','z'].every(k=>t[k]===layout.positions[i][k]));}
$('#restore-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>8*1024*1024)throw Error('This backup is too large.');const candidate=importBackup(await file.text());if(!validateGameContent(candidate))throw Error('The board in this backup is not compatible with this version.');openModal('Restore backup?',`<p>${candidate.completed.length} levels complete · ✧ ${candidate.coins} · Level ${candidate.level}. This replaces progress on this device.</p><div class="button-row"><button class="primary" id="confirm-restore">Restore</button><button class="secondary" data-action="backup">Export current first</button><button class="secondary" data-action="close">Cancel</button></div>`,'restore');$('#confirm-restore').onclick=()=>{const afterFailure=!ready;save=candidate;ready=true;if(!save.game){const l=levelFor(save.level);save.game={...createGame(l,layoutMap.get(l.layoutId)),level:save.level,completed:false};}selected=null;hint=[];zoom=1;panX=panY=0;const restored=persist();if(afterFailure){if(restored){location.reload();return;}ready=false;toast('The backup is valid, but your browser could not save it. Please allow site storage and try again.');return;}closeModal();render();toast('Backup restored');if(save.game.completed)winDialog();};}catch(error){toast('Could not restore: '+error.message);}});
