(async()=>{try{const [ls,ly]=await Promise.all([fetchJSON('./data/levels.json'),fetchJSON('./data/layouts.json')]);levels=ls.levels;layouts=Array.isArray(ly)?ly:ly.layouts;layoutMap=new Map(layouts.map(l=>[l.id,l]));if(!levels?.length||!layouts?.length)throw Error('The level library is missing.');const recovered=getStorageStatus().pendingRecovery?await recoverSave():null;if(recovered)save=recovered;if(getStorageStatus().corrupt)throw Error('Saved progress could not be recovered automatically. Export recovery data or restore a backup.');if(!validateGameContent(save))throw Error('Your saved board needs recovery. Your progress has been preserved. Please restore a compatible backup.');if(!save.game){const l=levelFor(save.level);save.game={...createGame(l,layoutMap.get(l.layoutId)),level:save.level,completed:false};}ready=true;render();persist();if(getStorageStatus().recovered)toast(getStorageStatus().error||'Your progress was recovered from its extra save copy.');if(save.game.completed)winDialog();offline=initOffline({beforeReload:()=>{if(!persist())throw Error('Please export a backup before updating.');},onStatus:status=>{offlineMessage=status.message;const box=$('#offline-status');if(box)box.textContent=offlineMessage;},onUpdate:()=>{updateReady=true;if(currentDialog==='settings')settings();}});}catch(e){$('#loading').hidden=true;$('#board-world').innerHTML=`<div class="fatal"><h2>Couldn't load the game</h2><p>${esc(e.message)}</p><p>Your saves are untouched.</p><button id="retry-load">Try again</button><button id="emergency-backup">Export recovery data</button><button id="emergency-restore">Restore backup</button></div>`;world.style.cssText='position:static;transform:none;width:auto;height:auto';$('#retry-load').onclick=()=>location.reload();$('#emergency-backup').onclick=backup;$('#emergency-restore').onclick=()=>$('#restore-file').click();}})();
